param([string]$EnvFile = ".env.production", [int]$TimeoutSeconds = 600)
$ErrorActionPreference = "Stop"; $Root=Split-Path -Parent $MyInvocation.MyCommand.Path; Set-Location $Root
function Fail([string]$Message){ throw "PRODUCCION: $Message" }
function Read-Env([string]$Name){ $line=Get-Content $EnvFile | Where-Object { $_ -match "^$([regex]::Escape($Name))=" } | Select-Object -First 1; if(-not $line){return $null}; return $line.Substring($line.IndexOf('=')+1).Trim() }
if(-not(Test-Path $EnvFile)){Fail "No existe $EnvFile"}; $domain=Read-Env 'DOMAIN'; if([string]::IsNullOrWhiteSpace($domain)){Fail 'Falta DOMAIN'}
$containers=@('clinica-mysql','clinica-eureka-server','clinica-auth-service','clinica-patient-service','clinica-appointment-service','clinica-clinical-service','clinica-finance-service','clinica-lab-service','clinica-operations-service','clinica-inventory-service','clinica-dashboard-service','clinica-content-service','clinica-encounter-service','clinica-survey-service','clinica-backup-service','clinica-api-gateway','clinica-frontend','clinica-caddy')
$deadline=(Get-Date).AddSeconds($TimeoutSeconds); Write-Host 'Esperando 18 contenedores de producción...' -ForegroundColor Cyan
while((Get-Date)-lt $deadline){ $pending=@(); foreach($name in $containers){ docker inspect $name *> $null; if($LASTEXITCODE -ne 0){$pending+="${name}:no-creado";continue}; $state=docker inspect -f '{{if .State.Health}}{{.State.Health.Status}}{{else}}{{.State.Status}}{{end}}' $name 2>$null; if($state -notin @('healthy','running')){$pending+="${name}:${state}"} }; if($pending.Count -eq 0){break}; Write-Host ('Pendientes: '+($pending -join ', ')) -ForegroundColor DarkYellow; Start-Sleep 8 }
if((Get-Date)-ge $deadline){Fail 'Los contenedores no alcanzaron estado saludable'}
docker compose --env-file $EnvFile -f docker-compose.production-secure.yml exec -T api-gateway curl -fsS http://localhost:8090/actuator/health *> $null; if($LASTEXITCODE -ne 0){Fail 'Gateway interno no saludable'}
$httpsDeadline=(Get-Date).AddSeconds([Math]::Min($TimeoutSeconds,600)); $ok=$false; while((Get-Date)-lt $httpsDeadline){try{$r=Invoke-WebRequest -Uri "https://$domain/" -TimeoutSec 20 -UseBasicParsing -ErrorAction Stop;if([int]$r.StatusCode -ge 200 -and [int]$r.StatusCode -lt 400){$ok=$true;break}}catch{};Start-Sleep 10}; if(-not $ok){Fail "https://$domain todavía no responde"}; Write-Host "OK - HTTPS público responde en https://$domain" -ForegroundColor Green
